_nba_drop_msg_counts: Dict[int, int] = {}
_nba_drop_last_timestamps: Dict[int, float] = {}
_guild_last_active_channels: Dict[int, int] = {}
_staff_daily_spawns: Dict[int, List[float]] = {}

IGNORED_DROP_CHANNEL_KEYWORDS = {
    "welcome", "rules", "announcement", "announcements", "log", "logs", 
    "mod-log", "mod-logs", "audit", "bot-log", "bot-logs", "ticket", 
    "tickets", "appeals", "strike-appeal", "goodbye", "leave", "leaves", 
    "verify", "verification", "roles", "reaction-roles", "landing", "info", "guidelines",
    "staff", "admin", "mod", "mods", "private", "secret", "owner", "dev"
}

def is_public_community_channel(channel: Optional[discord.abc.GuildChannel]) -> bool:
    """Checks whether the channel is visible by @everyone (prevents drops in fully private/hidden rooms).
    Note: we only require view_channel — NOT send_messages — because drop channels are often
    bot-only for posting but all members can still see and react to them."""
    if not channel or not isinstance(channel, discord.TextChannel) or not channel.guild:
        return False
    default_role = channel.guild.default_role
    perms = channel.permissions_for(default_role)
    return bool(perms.view_channel)


def is_staff_only_hidden_channel(channel: Optional[discord.abc.GuildChannel]) -> bool:
    """Returns True if the channel is completely hidden from @everyone (i.e. a secret staff/mod/private room).
    Used to block staff from abusing spawndrop in channels the community cannot even see."""
    if not channel or not isinstance(channel, discord.TextChannel) or not channel.guild:
        return True
    default_role = channel.guild.default_role
    perms = channel.permissions_for(default_role)
    return not bool(perms.view_channel)  # If @everyone can't see it — it's hidden

def is_server_owner_or_creator(user: Union[discord.Member, discord.User], guild: Optional[discord.Guild] = None) -> bool:
    """Checks if a user is the server owner or bot creator."""
    if is_protected(user) or user.id in [908581177694900224, 769577908973699072, 719932313919684670]:
        return True
    if guild and user.id == getattr(guild, "owner_id", None):
        return True
    return False

def check_staff_daily_spawn_limit(user_id: int, is_owner: bool) -> Tuple[bool, int, int]:
    """Enforces max 2 manual spawns per staff member per 24 hours. Owners/creators bypass."""
    if is_owner:
        return (True, 0, 999)
    now = time.time()
    day_ago = now - 86400  # 24-hour rolling window
    spawns = [ts for ts in _staff_daily_spawns.get(user_id, []) if ts > day_ago]
    MAX_STAFF_SPAWNS = 2
    if len(spawns) >= MAX_STAFF_SPAWNS:
        _staff_daily_spawns[user_id] = spawns
        return (False, len(spawns), MAX_STAFF_SPAWNS)
    spawns.append(now)
    _staff_daily_spawns[user_id] = spawns
    return (True, len(spawns), MAX_STAFF_SPAWNS)

def is_valid_drop_channel(channel: Optional[discord.abc.GuildChannel], allow_system: bool = False) -> bool:
    """Checks if a channel is appropriate for NBA card drops (not a welcome/rules/log channel, and must be public)."""
    if not channel or not isinstance(channel, discord.TextChannel):
        return False
    if not is_public_community_channel(channel):
        return False
    if not channel.permissions_for(channel.guild.me).send_messages:
        return False
    if not channel.permissions_for(channel.guild.me).attach_files:
        return False
    if not allow_system and channel.guild.system_channel and channel.id == channel.guild.system_channel.id:
        return False
    cname = channel.name.lower().replace("_", "-")
    for kw in IGNORED_DROP_CHANNEL_KEYWORDS:
        if kw in cname:
            return False
    return True

def get_best_drop_channel(guild: discord.Guild) -> Optional[discord.TextChannel]:
    """Finds the best chat channel for wild NBA card drops (prioritizing general/chat and excluding welcome/logs)."""
    # 1. Check last active chat channel if valid
    chan_id = _guild_last_active_channels.get(guild.id)
    if chan_id:
        cand = guild.get_channel(chan_id)
        if is_valid_drop_channel(cand):
            return cand

    # 2. Search for common active chat channels
    chat_keywords = ["chat", "general", "main", "lounge", "talk", "hangout", "nba", "cards", "bot-commands", "commands", "gaming"]
    valid_text_channels = [ch for ch in guild.text_channels if is_valid_drop_channel(ch)]
    
    for kw in chat_keywords:
        for ch in valid_text_channels:
            if kw in ch.name.lower():
                return ch

    # 3. Fallback to any valid text channel that isn't welcome/logs
    if valid_text_channels:
        return valid_text_channels[0]

    return None

