async def distribute_raid_boss_rewards(event: Dict[str, Any], guild: Optional[discord.Guild] = None, channel: Optional[Any] = None) -> List[Dict[str, Any]]:
    """Distributes the multi-tier rewards for a completed Community Raid Boss:
    - 1st Place (Top Damage): VC Pool or Prize Card
    - 2nd Place: Random Dark Matter (99 OVR)
    - 3rd Place: Random Dark Matter (99 OVR)
    - All Participants: Boss Raid Victory Pack
    """
    eid = int(event["id"])
    lb = await db.get_nba_raid_leaderboard(eid, limit=100)
    if not lb:
        return []

    results = []
    # 1. 1st Place -> Award exact event prize card or VC pool
    p1 = lb[0]
    u1_id = p1["user_id"]
    prize_id = event.get("prize_card_id", "dm-kobe-99")
    prize_name = event.get("prize_card_name", "Dark Matter Card")

    if str(prize_id).startswith("vc_"):
        try:
            vc_amt = int(re.sub(r'\D', '', prize_id))
        except Exception:
            vc_amt = 10000
        await db.add_user_vc(u1_id, vc_amt)
        await db.reward_nba_event_winner(eid, u1_id, prize_id, prize_name, count=1, rewarded_by="719932313919684670")
        results.append({
            "rank": 1,
            "user_id": u1_id,
            "prize": f"💰 **{vc_amt:,} VC Jackpot**",
            "dmg": p1["damage_dealt"]
        })
    else:
        prize_card_obj = get_nba_card(prize_id)
        tier_info = NBA_2K_TIERS.get(prize_card_obj.get("tier", "dark_matter") if prize_card_obj else "dark_matter", NBA_2K_TIERS["dark_matter"])
        prize_count = max(1, min(int(event.get("prize_count") or 1), 50))
        if prize_card_obj:
            await db.add_user_nba_card(u1_id, prize_card_obj["id"], source="event_raid_winner")
        await db.reward_nba_event_winner(eid, u1_id, prize_id, prize_name, count=prize_count, rewarded_by="719932313919684670")
        count_str = f" `[x{prize_count}]`" if prize_count > 1 else ""
        ovr_str = f"[{prize_card_obj.get('ovr', 99)}] " if prize_card_obj else ""
        results.append({
            "rank": 1,
            "user_id": u1_id,
            "prize": f"{tier_info['emoji']} {ovr_str}**{prize_name}**{count_str} ({tier_info['name']})",
            "dmg": p1["damage_dealt"]
        })

    # 2. 2nd & 3rd Place -> Dark Matter
    dm_cards = [c for c in NBA_2K_MOBILE_CARDS if c.get("tier") == "dark_matter"]
    if len(lb) > 1 and dm_cards:
        p2 = lb[1]
        c2 = random.choice(dm_cards)
        await db.add_user_nba_card(p2["user_id"], c2["id"], source="event_raid_2nd")
        results.append({"rank": 2, "user_id": p2["user_id"], "prize": f"🌌 [{c2['ovr']} OVR] {c2['name']} (Dark Matter)", "dmg": p2["damage_dealt"]})

    if len(lb) > 2 and dm_cards:
        p3 = lb[2]
        c3 = random.choice(dm_cards)
        await db.add_user_nba_card(p3["user_id"], c3["id"], source="event_raid_3rd")
        results.append({"rank": 3, "user_id": p3["user_id"], "prize": f"🌌 [{c3['ovr']} OVR] {c3['name']} (Dark Matter)", "dmg": p3["damage_dealt"]})

    # 3. All participants get a Boss Raid Victory Pack
    for p in lb:
        raid_card = roll_pack_card("boss_raid")
        if isinstance(raid_card, tuple):
            raid_card = raid_card[0]
        await db.add_user_nba_card(p["user_id"], raid_card["id"], source="event_raid_pack")

    return results


async def check_nba_event_progress(
    user: Union[discord.User, discord.Member],
    guild_id: Optional[int],
    action: str,
    channel: Optional[Any] = None
):
    """Monitors real-time tournament progress for automated event modes:
    - Card Collector Race: Automatically checks if user completed the entire tier
    """
    if not guild_id:
        return
    try:
        active = await db.get_active_nba_event(guild_id)
        if not active or active.get("status") != "active":
            return

        ev_type = active.get("event_type", "custom")
        eid = active["id"]

        if ev_type == "collector_race" and action == "card_acquired":
            target_tier = (active.get("target_tier") or "gold").lower().strip()
            tier_cards = [c for c in NBA_2K_MOBILE_CARDS if c.get("tier") == target_tier]
            if tier_cards:
                user_cards = await db.get_user_nba_cards(user.id)
                owned_cids = set(c["card_id"].lower() for c in user_cards)
                all_owned = all(c["id"].lower() in owned_cids for c in tier_cards)
                if all_owned:
                    prize_id = active.get("prize_card_id", "excl-jordan-99")
                    prize_name = active.get("prize_card_name", "Exclusive Card")
                    await db.reward_nba_event_winner(eid, user.id, prize_id, prize_name, rewarded_by="719932313919684670")
                    await db.end_nba_event(eid)

                    t_info = NBA_2K_TIERS.get(target_tier, NBA_2K_TIERS["gold"])
                    prize_obj = get_nba_card(prize_id)
                    ann_embed = discord.Embed(
                        title="🏁 CARD COLLECTOR RACE CHAMPION CROWNED!",
                        description=(
                            f"🎉 **{user.mention} is the FIRST to collect all {t_info['emoji']} {t_info['name']} tier cards!**\n\n"
                            f"🏆 **Event:** **{active['name']}** (ID #{eid})\n"
                            f"👑 **Grand Prize Awarded:** 👑 **[{prize_obj['ovr'] if prize_obj else 99} OVR] {prize_name}**\n\n"
                            f"✨ *The Exclusive Immortal card has been deposited directly into their collection binder!*"
                        ),
                        color=0xFF1493
                    )
                    ann_embed.timestamp = discord.utils.utcnow()
                    target_chan_id = await db.get_nba_event_channel(guild_id)
                    chan = None
                    if channel and hasattr(channel, "guild") and channel.guild:
                        chan = channel.guild.get_channel(target_chan_id) if target_chan_id else channel
                    elif channel:
                        chan = channel

                    if chan and hasattr(chan, "send"):
                        await chan.send(embed=ann_embed)

                    try:
                        dm_embed = discord.Embed(
                            title="🏆 YOU WON THE CARD COLLECTOR RACE!",
                            description=(
                                f"🎉 You were the first to complete the **{t_info['name']}** tier in **{active['name']}**!\n\n"
                                f"👑 You have received your **Exclusive Immortal {prize_name}**!"
                            ),
                            color=0xFF1493
                        )
                        await user.send(embed=dm_embed)
                    except Exception:
                        pass
    except Exception as e:
        logger.error(f"Error in check_nba_event_progress: {e}", exc_info=True)


# ── Server Event & Tournament Slash Command Group ──────────────────────────

event_group = app_commands.Group(name="event", description="🏆 Server Event & Tournament System")

@event_group.command(name="create", description="👑 Creator: Launch a new server event or tournament")
@app_commands.describe(
    name="Event name (e.g. 'Summer Championship')",
    prize_card="Card ID or player name (e.g. 'dm-kobe-99', 'Kobe Bryant', 'excl-jordan-99')",
    prize_count="Number of copies of the prize card to award (default 1)",
    duration_hours="Duration of event in hours (e.g. 24, 48, 72, default 48)",
    event_type="Select event type / format",
    description="Event description and lore",
    rules="Specific rules or winning conditions",
    boss_name="Name of Raid Boss (for Raid events only)",
    boss_hp="Boss HP (for Raid events only, default 50000)"
)
@app_commands.choices(event_type=[
    app_commands.Choice(name="🎯 Custom / Manual Challenge", value="custom"),
    app_commands.Choice(name="🏆 Card Collector Race (First to complete a tier)", value="collector_race"),
    app_commands.Choice(name="🌟 Fuse Frenzy (Most Holo Foil cards created)", value="fuse_frenzy"),
    app_commands.Choice(name="📦 Pack Opening Marathon (Most packs ripped)", value="pack_marathon"),
    app_commands.Choice(name="👾 Community Raid Boss (Server defeats Boss together)", value="raid"),
])
@app_commands.guild_only()
async def event_create_slash_cmd(
    interaction: discord.Interaction,
    name: str,
    prize_card: str,
    prize_count: Optional[int] = 1,
    duration_hours: Optional[float] = 48.0,
    event_type: Optional[str] = "custom",
    description: Optional[str] = "",
    rules: Optional[str] = "",
    boss_name: Optional[str] = "Titan Mecha Giannis",
    boss_hp: Optional[int] = 50000
):
    try:
        if not is_event_creator(interaction.user):
            await interaction.response.send_message("❌ Only the Bot Creator (`<@719932313919684670>`) can create events.", ephemeral=True)
            return

        await interaction.response.defer()

        active = await db.get_active_nba_event(interaction.guild_id)
        if active:
            await interaction.followup.send(f"❌ There is already an active event in this server: **{active['name']}** (ID #{active['id']}).\nUse `/event end` or `/event cancel` before launching a new event.", ephemeral=True)
            return

        prize_obj = get_nba_card(prize_card)
        if not prize_obj:
            await interaction.followup.send(f"❌ Prize card `{prize_card}` not found in catalog.", ephemeral=True)
            return

        ev_type = event_type or "custom"
        b_name = boss_name if ev_type == "raid" else ""
        b_hp = max(1000, boss_hp or 50000) if ev_type == "raid" else 0
        dur = max(0.5, float(duration_hours or 48.0))
        p_count = max(1, min(prize_count or 1, 50))

        event_id = await db.create_nba_event(
            guild_id=interaction.guild_id,
            name=name,
            description=description or f"Compete in the {name} event!",
            event_type=ev_type,
            prize_card_id=prize_obj["id"],
            prize_card_name=prize_obj["name"],
            channel_id=interaction.channel_id,
            duration_hours=dur,
            rules=rules or "Standard server event rules apply.",
            boss_name=b_name,
            boss_hp=b_hp
        )

        if not event_id:
            await interaction.followup.send("❌ Failed to create event in database. Please try again.", ephemeral=True)
            return

        ends_at = int(time.time() + (dur * 3600))
        tier_info = NBA_2K_TIERS.get(prize_obj.get("tier", "dark_matter"), NBA_2K_TIERS["gold"])
        count_str = f" `[x{p_count}]`" if p_count > 1 else ""
        
        type_labels = {
            "custom": "🎯 **Custom / Manual Challenge**",
            "collector_race": "🏆 **Card Collector Race** — First member to complete a specific tier wins!",
            "fuse_frenzy": "🌟 **Fuse Frenzy** — Most Holo Foil cards created using `/nbafuse` wins!",
            "pack_marathon": "📦 **Pack Opening Marathon** — Most card packs opened using `/openpack` wins!",
            "raid": f"👾 **Community Raid Boss Battle** — Server members team up with `/event raid` to defeat **{b_name}** ({b_hp:,} HP)! Top damage dealer wins the prize!"
        }

        ann_embed = discord.Embed(
            title=f"🏆 NEW SERVER EVENT: {name}",
            description=(
                f"{type_labels.get(ev_type, '🎯 **Special Server Event**')}\n\n"
                f"📝 **Description:**\n{description or 'The Creator has initiated a new competitive event!'}\n\n"
                f"📜 **Rules & Conditions:**\n{rules or 'Open to all server members. Play fair and have fun!'}\n\n"
                f"👑 **Grand Prize:** {tier_info['emoji']} **[{prize_obj['ovr']} OVR] {prize_obj['name']}**{count_str} *({tier_info['name']})*\n"
                f"• **Card ID:** `{prize_obj['id']}`\n"
                f"• **Badges:** {', '.join(prize_obj.get('badges', []))}\n\n"
                f"⏳ **Event Ends:** <t:{ends_at}:R> (<t:{ends_at}:F>)\n"
                f"👑 **Hosted by Creator:** <@719932313919684670>"
            ),
            color=0xFF1493
        )
        ann_embed.set_thumbnail(url=interaction.guild.icon.url if interaction.guild and interaction.guild.icon else None)
        ann_embed.set_footer(text=f"Event ID: #{event_id} • Use /event status or /event raid to participate")
        ann_embed.timestamp = discord.utils.utcnow()

        img_io = generate_nba_card_graphic(prize_obj)
        img_io.seek(0)
        ann_file = discord.File(img_io, filename=f"prize_{prize_obj['id']}.png")
        ann_embed.set_image(url=f"attachment://prize_{prize_obj['id']}.png")

        saved_channel_id = await db.get_nba_event_channel(interaction.guild_id)
        target_channel = interaction.guild.get_channel(saved_channel_id) if saved_channel_id and interaction.guild else interaction.channel

        if target_channel and target_channel.id != interaction.channel_id:
            await target_channel.send(embed=ann_embed, file=ann_file)
            await interaction.followup.send(f"✅ Event **{name}** (ID #{event_id}) created and announced in {target_channel.mention}!", ephemeral=True)
        else:
            await interaction.followup.send(embed=ann_embed, file=ann_file)

    except Exception as e:
        logger.error(f"Error in /event create: {e}", exc_info=True)
        if interaction.response.is_done():
            await interaction.followup.send(f"❌ Error creating event: {e}", ephemeral=True)
        else:
            await interaction.response.send_message(f"❌ Error creating event: {e}", ephemeral=True)


