@bot.tree.command(name="nbatrade", description="🤝 Open an interactive multi-card & VC trade panel with another member")
@app_commands.describe(
    user="The member you want to trade cards / VC with",
    your_card="Optional: Initial Card ID or Player Name you are offering",
    their_card="Optional: Initial Card ID or Player Name you are requesting",
    your_vc="Optional: Initial VC amount you want to offer"
)
@app_commands.guild_only()
@app_commands.checks.cooldown(1, 5.0, key=lambda i: (i.guild_id, i.user.id))
async def nbatrade_slash_cmd(
    interaction: discord.Interaction,
    user: discord.Member,
    your_card: Optional[str] = None,
    their_card: Optional[str] = None,
    your_vc: Optional[int] = 0
):
    try:
        await interaction.response.defer()
        if user.id == interaction.user.id or user.bot:
            await interaction.followup.send("❌ You cannot trade cards with yourself or bots.", ephemeral=True)
            return

        init_vc_a = max(0, int(your_vc or 0))
        if init_vc_a > 0:
            sender_vc = await db.get_user_vc(interaction.user.id)
            if sender_vc < init_vc_a:
                await interaction.followup.send(f"❌ You only have **`{sender_vc:,}` VC**, cannot offer **`{init_vc_a:,}` VC**.", ephemeral=True)
                return

        cards_a = []
        cards_b = []

        if your_card:
            c_a = get_nba_card(your_card)
            if not c_a:
                await interaction.followup.send(f"❌ Your offered card `{your_card}` was not found.", ephemeral=True)
                return
            if c_a.get("tier") == "exclusive" or str(c_a.get("id", "")).startswith("excl-") or c_a.get("is_exclusive"):
                await interaction.followup.send("❌ **Exclusive cards cannot be traded!** They are non-transferable account-bound trophies.", ephemeral=True)
                return
            sender_cards = [c["card_id"].lower() for c in await db.get_user_nba_cards(interaction.user.id)]
            if c_a["id"].lower() not in sender_cards:
                await interaction.followup.send(f"❌ You do not own **{c_a['name']}** (`{c_a['id']}`).", ephemeral=True)
                return
            cards_a.append(c_a)

        if their_card:
            c_b = get_nba_card(their_card)
            if not c_b:
                await interaction.followup.send(f"❌ The requested card `{their_card}` was not found.", ephemeral=True)
                return
            if c_b.get("tier") == "exclusive" or str(c_b.get("id", "")).startswith("excl-") or c_b.get("is_exclusive"):
                await interaction.followup.send("❌ **Exclusive cards cannot be traded!** They are non-transferable account-bound trophies.", ephemeral=True)
                return
            target_cards = [c["card_id"].lower() for c in await db.get_user_nba_cards(user.id)]
            if c_b["id"].lower() not in target_cards:
                await interaction.followup.send(f"❌ {user.mention} does not own **{c_b['name']}** (`{c_b['id']}`).", ephemeral=True)
                return
            cards_b.append(c_b)

        embed = build_multi_trade_embed(interaction.user, user, cards_a, cards_b, status="pending", vc_a=init_vc_a)
        view = NBACardTradeView(interaction.user, user, cards_a, cards_b, vc_a=init_vc_a)
        msg = await interaction.followup.send(
            content=f"🔔 {user.mention}, you have received a card & VC trade proposal from {interaction.user.mention}!",
            embed=embed,
            view=view
        )
        view.message = msg
    except Exception as e:
        logger.error(f"Error in /nbatrade: {e}", exc_info=True)
        if interaction.response.is_done():
            await interaction.followup.send(f"❌ Error: {e}", ephemeral=True)
        else:
            await interaction.response.send_message(f"❌ Error: {e}", ephemeral=True)


@bot.tree.command(name="nbatop", description="🏆 View the server NBA 2K Mobile Card Collector & VC Leaderboard")
@app_commands.describe(category="Leaderboard category to rank members by")
@app_commands.choices(
    category=[
        app_commands.Choice(name="🎴 Most Cards Collected", value="cards"),
        app_commands.Choice(name="💰 VC Millionaires (Highest Balance)", value="vc"),
    ]
)
@app_commands.guild_only()
@app_commands.checks.cooldown(1, 5.0, key=lambda i: (i.guild_id, i.user.id))
async def nbatop_slash_cmd(interaction: discord.Interaction, category: Optional[str] = "cards"):
    try:
        await interaction.response.defer()
        cat = category or "cards"
        if cat == "vc":
            query = "SELECT user_id, vc_balance, cards_claimed FROM user_nba_economy WHERE user_id != '719932313919684670' ORDER BY vc_balance DESC LIMIT 10"
            rows = await db.fetch(query)
            embed = discord.Embed(
                title="🏆 NBA 2K Mobile • VC Millionaires Leaderboard",
                description="The richest Virtual Currency balances on the server!\n\n",
                color=discord.Color.gold()
            )
            if not rows:
                embed.description += "No VC records found yet. Claim daily VC with `/nbadaily`!"
            else:
                for idx, r in enumerate(rows, 1):
                    med = "🥇" if idx == 1 else "🥈" if idx == 2 else "🥉" if idx == 3 else f"**#{idx}**"
                    embed.description += f"{med} <@{r['user_id']}> — `💰 {r['vc_balance']:,} VC` *({r.get('cards_claimed', 0)} cards claimed)*\n"
        else:
            query = """
            SELECT user_id, COUNT(*) as total_cards, COUNT(DISTINCT card_id) as unique_cards
            FROM user_nba_cards
            WHERE user_id != '719932313919684670'
            GROUP BY user_id
            ORDER BY total_cards DESC
            LIMIT 10
            """
            rows = await db.fetch(query)
            embed = discord.Embed(
                title="🏆 NBA 2K Mobile • Top Card Collectors Leaderboard",
                description=f"The greatest card collectors on the server ({len(NBA_2K_MOBILE_CARDS)} cards in catalog)!\n\n",
                color=discord.Color.purple()
            )
            if not rows:
                embed.description += "No cards collected yet! Open your first pack with `/openpack`!"
            else:
                for idx, r in enumerate(rows, 1):
                    med = "🥇" if idx == 1 else "🥈" if idx == 2 else "🥉" if idx == 3 else f"**#{idx}**"
                    embed.description += f"{med} <@{r['user_id']}> — `🎴 {r['total_cards']} Cards` *({r['unique_cards']}/{len(NBA_2K_MOBILE_CARDS)} unique)*\n"

        embed.set_footer(text="NBA 2K Mobile Dex Leaderboard • Use /nbadex to view your collection")
        embed.timestamp = discord.utils.utcnow()
        await interaction.followup.send(embed=embed)
    except Exception as e:
        logger.error(f"Error in /nbatop: {e}", exc_info=True)
        if interaction.response.is_done():
            await interaction.followup.send(f"❌ Error: {e}", ephemeral=True)
        else:
            await interaction.response.send_message(f"❌ Error: {e}", ephemeral=True)


